      {
        id: "csharp-c14-u2-l4-indices-clustered-e-non-clustered-em-consultas-sql",
        title: "Índices Clustered e Non-Clustered: A física de armazenamento no disco",
        subtitle: "Performance de busca · Compreendendo árvores B-Tree e a ordem física das tabelas",
        theory: "Sem índices, o banco de dados executa varredura completa da tabela (Table Scan O(n)). O índice Clustered define a própria ordem física em que os registros residem no disco (geralmente na PK). Índices Non-Clustered criam estruturas B-Tree separadas contendo ponteiros para as linhas físicas.",
        questions: [
          q("Quantos índices Clustered (Clusterizados) uma tabela relacional pode ter no máximo?", "Exatamente um; pois os dados físicos do disco só podem estar fisicamente ordenados de uma única maneira", ["Quantos forem necessários","Até 10"], "O índice clusterizado organiza a disposição física das páginas da própria tabela no disco."),
          q("O que é um \"Table Scan\" (ou Index Scan completo) e por que ele degrada o banco em tabelas gigantes?", "É a leitura sequencial de absolutamente todas as páginas da tabela do disco para encontrar um único registro", ["É uma cópia da tabela","É a limpeza de registros antigos"], "Varre milhões de linhas consumindo I/O massivo de disco; em tabelas grandes deve ser substituído por Index Seek."),
          q("O que a operação \"Index Seek\" representa no plano de execução de uma consulta SQL?", "Navegação direta na árvore B-Tree alcançando o registro desejado em tempo logarítmico O(log n)", ["Uma falha de índice","Uma ordenação em memória"], "Index Seek é a forma mais veloz de busca, percorrendo a hierarquia de nós da B-Tree diretamente ao alvo."),
          q("Qual é o custo de adicionar dezenas de índices Non-Clustered em tabelas com milhões de inserções?", "Cada INSERT, UPDATE ou DELETE precisa atualizar todos os índices existentes, degradando a escrita", ["O banco consome menos disco","Nenhum custo"], "Índices aceleram leituras de consultas, mas cobram pedágio computacional em operações de escrita."),
          t("Qual estrutura de árvore balanceada é utilizada pelos bancos de dados para implementar índices velozes?", ["B-Tree"], "A árvore B-Tree provê buscas, inserções e intervalos em complexidade O(log n)."),
          g("Complete o comando fluente para indexar a coluna Documento para buscas rápidas:", ["HasIndex"], "HasIndex cria um índice na coluna.", "builder.Entity<Pessoa>().____(p => p.Documento);"),
          o("Ordene a eficiência de localização de um registro no plano de execução do banco:", ["Table Scan: pior caso; varre todo o disco lendo milhões de linhas sem nenhum índice","Index Scan: varre todo o índice secundário de ponta a ponta sem pular páginas","Index Seek com Key Lookup: localiza no índice secundário e busca dados extras no clusterizado","Index Seek puro coberto (Covering Index): busca direta logarítmica com todos os dados no índice"], "Table scan ineficiente, index scan, seek com lookup e covering index ideal."),
          p("Associe o tipo de índice ao seu comportamento no banco de dados:", [["Índice Clustered","Determina a ordenação física dos registros nas páginas de dados do disco"],["Índice Non-Clustered","Estrutura separada com chaves e ponteiros apontando para as linhas físicas"],["Covering Index (Índice Coberto)","Inclui todas as colunas da consulta no próprio índice evitando lookups"],["Index Seek","Navegação cirúrgica na B-Tree que encontra o registro sem ler a tabela inteira"]], "Projetar índices com critério garante que sistemas com bilhões de linhas respondam em milissegundos.")
        ]
      },
      {
        id: "csharp-c14-u2-l5-indices-compostos-e-a-regra-do-prefixo-mais-a-esquerda",
        title: "Índices compostos e a regra do prefixo mais à esquerda (Leftmost Prefix)",
        subtitle: "Consultas multi-coluna · Como a ordem das colunas no índice define sua utilidade",
        theory: "Índices compostos reúnem duas ou mais colunas: CREATE INDEX IX_Vendas ON Vendas(Ano, Mes). Pela regra do prefixo mais à esquerda, esse índice acelera buscas por (Ano) ou por (Ano, Mes), mas é completamente inútil para consultas que filtram apenas por (Mes) sem especificar o Ano correspondente.",
        questions: [
          q("O que estabelece a regra do \"Prefixo mais à esquerda\" (Leftmost Prefix) em índices compostos?", "O índice só pode ser aproveitado se a consulta filtrar a partir da primeira coluna definida na ordem do índice", ["As colunas devem estar em maiúsculas","O índice só funciona no lado esquerdo do disco"], "Assim como uma lista telefônica ordenada por Sobrenome e Nome não ajuda a buscar por Primeiro Nome isolado."),
          q("Se criarmos um índice composto sobre (EmpresaId, Status, Data), quais filtros poderão utilizar o índice com Seek?", "Filtros por (EmpresaId), por (EmpresaId, Status) e por (EmpresaId, Status, Data)", ["Apenas filtros por Data","Qualquer combinação aleatória"], "A busca aproveita o índice enquanto a sequência de colunas informadas começar do primeiro elemento à esquerda."),
          q("Por que a seletividade da coluna deve ditar qual coluna vem primeiro no índice composto?", "Colunas com alta seletividade (que reduzem drasticamente o conjunto de linhas) filtram mais cedo", ["Para economizar espaço de letras","Para facilitar o código C#"], "Posicionar colunas que eliminam a maioria dos registros no início torna as buscas mais afuniladas e velozes."),
          q("O que são as \"colunas incluídas\" (INCLUDE) em um índice non-clustered?", "Colunas anexadas apenas no nível folha do índice para evitar Lookups sem aumentar o custo da árvore B-Tree", ["Colunas que aceitam números negativos","Colunas que viram chaves primárias"], "INCLUDE enriquece o índice para cobrir a consulta sem inflar o tamanho das páginas intermediárias de busca."),
          t("Qual regra da teoria relacional exige que filtros utilizem as primeiras colunas do índice composto?", ["prefixo"], "A regra do prefixo mais à esquerda governa a utilização de índices compostos."),
          g("Complete o índice composto fluente sobre Estado e Cidade no EF Core:", ["HasIndex"], "HasIndex aceita expressões com tipos anônimos para chaves compostas.", "builder.Entity<Endereco>().____(e => new { e.Estado, e.Cidade });"),
          o("Ordene as consultas conforme a capacidade de usar o índice (Cidade, Bairro, Rua):", ["WHERE Cidade = \"SP\" AND Bairro = \"Centro\" AND Rua = \"Direita\" - utiliza 100% do índice","WHERE Cidade = \"SP\" AND Bairro = \"Centro\" - utiliza as duas primeiras colunas do índice com Seek","WHERE Cidade = \"SP\" - utiliza a primeira coluna do prefixo com grande eficiência","WHERE Bairro = \"Centro\" - não aproveita o índice por violar a regra do prefixo à esquerda"], "Uso total do índice, uso das duas primeiras, uso do prefixo inicial e falha por omissão do prefixo."),
          p("Associe a estrutura do índice ao seu ganho operacional:", [["Índice Composto (A, B)","Otimiza buscas combinadas filtrando primeiro por A e depois refinando por B"],["Cláusula INCLUDE (C)","Disponibiliza o dado C no nível folha tornando o índice 100% coberto"],["Alta Seletividade","Coluna com valores altamente distintos que descarta grande volume de linhas"],["Index Skip Scan","Otimização avançada de alguns motores para tentar saltar valores repetidos no prefixo"]], "Dominar a ordenação de colunas em índices compostos é o ápice da otimização de bancos relacionais.")
        ]
      }
