        questions: [
          q("Por que projetar com .Select(x => new Dto { ... }) é muito mais rápido que retornar a entidade completa?", "Porque o EF Core emite um SELECT apenas das colunas listadas no DTO, poupando I/O de rede e dispensando tracking", ["Porque o DTO é compilado em C++","Porque ele não acessa o disco"], "Elimina a sobrecarga de transferir colunas pesadas não utilizadas e evita cadastrar entidades no ChangeTracker."),
          q("Podemos mapear relacionamentos dentro de um .Select sem precisar de .Include() explícito?", "Sim; projetar propriedades relacionadas diretamente no Select gera os JOINs adequados automaticamente no SQL", ["Não, Include é obrigatório sempre","Apenas com procedures"], "O EF Core analisa a navegação dentro do Select e cria os JOINs necessários de forma otimizada."),
          q("Projeções com Select colocam as instâncias de DTO dentro do Change Tracker do DbContext?", "Não; DTOs e tipos anônimos nunca são rastreados pelo ChangeTracker, funcionando como consultas de somente leitura puras", ["Sim, são rastreados normalmente","Apenas se tiverem Id"], "Projeções são intrinsecamente livres de tracking, oferecendo altíssimo throughput para leitura de dados."),
          q("Qual é o benefício de performance de projetar diretamente para records ou DTOs em endpoints de listagem de APIs?", "Redução drástica no consumo de memória RAM do servidor e tempo de resposta significativamente menor para o cliente", ["O endpoint não precisa de autenticação","Aumenta a velocidade do browser"], "Listagens web só precisam de poucos campos (ex: Id e Nome); projetá-los é a regra de ouro em APIs corporativas."),
          t("Qual operador LINQ permite escolher as colunas exatas que devem ser selecionadas no banco?", ["Select"], "Select projeta apenas as colunas especificadas no SQL gerado."),
          g("Complete a projeção cirúrgica de colunas para o DTO de listagem:", ["Select"], "Select gera SELECT apenas das colunas especificadas.", "var dtos = await context.Usuarios.____(u => new UsuarioDto(u.Id, u.Nome)).ToListAsync();"),
          o("Ordene a jornada de uma consulta otimizada com projeção no EF Core:", ["A aplicação precisa listar 500 produtos exibindo apenas Id, Nome e Preco","O código executa .Select(p => new ProdutoResumo(p.Id, p.Nome, p.Preco))","O provedor do EF Core emite o SQL cirúrgico: SELECT p.Id, p.Nome, p.Preco FROM Produtos","O cliente recebe o payload leve sem que o ChangeTracker precise gerenciar nada"], "Necessidade de poucos campos, aplicação do Select, emissão de query enxuta e retorno sem tracking."),
          p("Associe a abordagem de consulta ao seu impacto no sistema:", [["Consulta de Entidade Completa","Gera SELECT com todas as colunas da tabela e registra no ChangeTracker"],["Projeção com .Select(...)","Gera SELECT cirúrgico contendo apenas as colunas mapeadas no DTO"],["Navegação dentro do Select","O EF Core gera os JOINs automaticamente sem exigir .Include() prévio"],["Tipos Anônimos / DTOs","Objetos de dados leves e imutáveis ideais para retornos de leitura em APIs"]], "Priorizar projeções com Select em consultas de leitura é o segredo para bancos relacionais que nunca engargalam.")
        ]
