      {
        id: "csharp-c14-u5-l4-o-problema-do-n-mais-1-e-split-queries-assplitquery",
        title: "O problema do N+1 e o dilema de Split Queries: AsSplitQuery vs AsSingleQuery",
        subtitle: "Explosão cartesiana vs Múltiplas conexões · Dominando o carregamento de coleções filhas",
        theory: "O problema do N+1 ocorre quando a aplicação faz 1 query para o pai e N queries individuais para cada filho. O EF Core previne isso com JOINs, mas múltiplos Includes geram duplicação massiva de dados (explosão cartesiana). O método .AsSplitQuery() divide a busca em queries separadas e limpas para cada tabela.",
        questions: [
          q("O que é o clássico problema de consulta \"N+1\" em aplicações com banco de dados?", "A aplicação executa 1 query para obter N registros pais e depois executa mais N queries separadas para buscar os filhos de cada um", ["O banco faz 1 inserção por segundo","O compilador gera erro de compilação"], "Gera centenas de viagens de ida e volta pela rede (roundtrips), derrubando a performance do banco."),
          q("Como o método .AsSplitQuery() introduzido no EF Core resolve o problema da explosão cartesiana de múltiplos Includes?", "Ele divide a consulta em comandos SELECT separados para cada tabela relacionada, combinando os dados em memória", ["Ele apaga as tabelas duplicadas","Ele desativa as foreign keys"], "Evita a transmissão de dados repetidos pela rede gerados por JOINs com múltiplas coleções filhas."),
          q("Qual é a desvantagem potencial de utilizar AsSplitQuery em vez de AsSingleQuery?", "Exige múltiplas viagens de rede (roundtrips) e pode sofrer inconsistências se os dados mudarem entre as queries no banco", ["O código não compila no Linux","Consome mais espaço em disco"], "Se uma linha for alterada no exato instante entre o primeiro e o segundo SELECT, pode haver leve discrepância se não estiver em transação."),
          q("Como configurar o AsSplitQuery como padrão global para todas as consultas do DbContext?", "optionsBuilder.UseSqlServer(str, o => o.UseQuerySplittingBehavior(QuerySplittingBehavior.SplitQuery))", ["DbContext.EnableSplit()","Program.SetSplitQueries()"], "Pode ser configurado globalmente nas opções do provedor relacional e sobrescrito pontualmente nas consultas."),
          t("Qual método de extensão do EF Core divide uma consulta hierárquica complexa em múltiplos comandos SQL enxutos?", ["AsSplitQuery"], "AsSplitQuery impede a multiplicação de linhas duplicadas pela rede."),
          g("Complete a instrução para dividir a consulta pesada em comandos SQL separados:", ["AsSplitQuery"], "AsSplitQuery separa os selects de tabelas relacionadas.", "var dados = await context.Blogs.Include(b => b.Posts).Include(b => b.Autores).____().ToListAsync();"),
          o("Ordene a decisão entre AsSingleQuery e AsSplitQuery no EF Core:", ["Analisar a consulta hierárquica construída com múltiplos relacionamentos de coleção (1:N)","Constatar que o JOIN único gera produto cartesiano com gigabytes de dados repetidos na rede","Aplicar .AsSplitQuery() para que o EF Core envie comandos SELECT pontuais e rápidos por tabela","Avaliar envolver em transação com isolamento SNAPSHOT caso a consistência concorrente seja crítica"], "Análise de hierarquia, detecção de explosão cartesiana, aplicação de AsSplitQuery e garantia transacional."),
          p("Associe a estratégia de carregamento ao seu comportamento de rede:", [["AsSingleQuery (Padrão)","Gera um único comando SQL com múltiplos JOINs; risco de explosão cartesiana"],["AsSplitQuery","Gera comandos SQL separados para a raiz e para cada coleção; elimina dados repetidos"],["Problema do N+1","Antipadrão onde cada filho é buscado em uma query separada dentro de um laço"],["Lazy Loading não intencional","Causa número um do problema N+1 ao acessar propriedades de navegação em loops"]], "Entender quando usar AsSplitQuery e eliminar o N+1 garante máxima eficiência de tráfego de rede.")
        ]
      },
      {
        id: "csharp-c14-u5-l5-consultas-sem-rastreamento-com-asnotracking",
        title: "Consultas sem rastreamento com AsNoTracking e AsNoTrackingWithIdentityResolution",
        subtitle: "Modo somente leitura · Otimizando consultas de exibição com consumo mínimo de memória",
        theory: "Por padrão, o EF Core cadastra todas as entidades consultadas no Change Tracker para monitorar mutações. Em operações de somente leitura (como relatórios ou respostas de APIs GET), usar .AsNoTracking() desliga esse rastreamento, proporcionando economias drásticas de memória e tempo de CPU.",
        questions: [
          q("O que o método .AsNoTracking() faz ao ser aplicado em uma consulta do EF Core?", "Instrui o EF Core a não registrar as entidades retornadas no ChangeTracker, tratando-as como dados de somente leitura", ["Apaga as entidades do banco","Desativa os índices de busca"], "Economiza a memória de snapshot do ChangeTracker e poupa o processamento de auditoria interna."),
          q("O que acontece se modificarmos uma propriedade de uma entidade obtida com AsNoTracking() e chamarmos SaveChangesAsync()?", "A alteração NÃO será salva no banco de dados, pois o EF Core não está rastreando o objeto", ["O banco lança exceção fatal","Salva normalmente"], "Como o objeto não está sob vigilância do contexto, o SaveChanges ignora qualquer alteração feita nele."),
          q("Qual método deve ser usado quando precisamos de AsNoTracking mas a consulta repete a mesma entidade pai várias vezes?", "AsNoTrackingWithIdentityResolution()", ["AsNoTrackingUnique()","AsNoTrackingStrict()"], "Ele assegura que múltiplas referências ao mesmo ID compartilhem a mesma instância em memória sem reter no tracker."),
          q("Como desativar o rastreamento de entidades por padrão em todo o DbContext para uma aplicação que é 90% leitura?", "Configurando context.ChangeTracker.QueryTrackingBehavior = QueryTrackingBehavior.NoTracking", ["Deletando a pasta do ChangeTracker","Usando conexões somente leitura"], "Pode-se configurar o contexto como NoTracking por padrão e usar .AsTracking() apenas onde for gravar alterações."),
          t("Qual método de extensão do EF Core desativa o monitoramento de alterações de entidades em consultas de leitura?", ["AsNoTracking"], "AsNoTracking proporciona grande ganho de desempenho em cenários de leitura."),
          g("Complete a consulta de leitura otimizada sem cadastro no ChangeTracker:", ["AsNoTracking"], "AsNoTracking poupa alocação de metadados no contexto.", "var produtos = await context.Produtos.____().ToListAsync();"),
          o("Ordene a rotina de uma consulta de alto desempenho para endpoint GET de API:", ["Receber os filtros de busca enviados pelo cliente na requisição HTTP","Construir a consulta LINQ aplicando .AsNoTracking() logo após o DbSet","Aplicar filtros de Where, ordenação e paginação com Skip e Take","Materializar e retornar os dados sem gastar memória com ChangeTracker"], "Filtros recebidos, aplicação de AsNoTracking, refinamento com LINQ e retorno ultrarrápido."),
          p("Associe a configuração de rastreamento ao seu caso de uso:", [["AsNoTracking()","Ideal para consultas de leitura pura em APIs, relatórios e telas estáticas"],["AsNoTrackingWithIdentityResolution()","Leitura sem rastreamento que mantém unicidade de instâncias repetidas"],["AsTracking()","Rastreia a entidade para que alterações feitas sejam salvas no próximo SaveChanges"],["QueryTrackingBehavior.NoTracking","Configuração global para adotar o modo somente leitura por padrão no contexto"]], "Adotar AsNoTracking como padrão em consultas de leitura é o mandamento número um de performance no EF Core.")
        ]
      }
